package cl.nexbyte.siger.institucional.windows;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledOnOs;
import org.junit.jupiter.api.condition.OS;
import static org.junit.jupiter.api.Assertions.*;
@EnabledOnOs(OS.WINDOWS)
class ArranqueWindowsTest {
    static Map<String,String> base(){var p=new HashMap<String,String>();p.put("siger.windows.modo","PRELIMINAR_SIN_DOCUMENTAL");p.put("institucional.db.url","jdbc:mysql://127.0.0.1:3306/siger_institucional_windows_qa?sslMode=VERIFY_IDENTITY");p.put("institucional.db.user","siger_windows_qa_app");p.put("institucional.db.password","valor-sintetico-no-credencial");p.put("server.ssl.key-store","file:/fixture.p12");p.put("server.ssl.key-store-password","valor-sintetico");return p;}
    @Test void recibeConfiguracionSinHabilitarCorreoORecuperacion(){var p=ArranqueWindows.configurar(base());for(String key:List.of("institucional.notificaciones.correo.automatico","institucional.documental.habilitada","institucional.formulario-completo.habilitado","institucional.v2.habilitada","institucional.integracion.habilitada","spring.flyway.enabled"))assertEquals("false",p.get(key));assertEquals("127.0.0.1",p.get("server.address"));assertEquals("true",p.get("server.ssl.enabled"));assertEquals("SIMULADO",p.get("institucional.notificaciones.correo.modo"));}
    @Test void rechazaHistoricoMigradorOtroPuertoYDesactivarTLS(){for(var entry:List.of(Map.entry("institucional.db.url",base().get("institucional.db.url").replace("windows_qa","windows_lab")),Map.entry("institucional.db.url",base().get("institucional.db.url").replace("VERIFY_IDENTITY","DISABLED")),Map.entry("institucional.db.user","siger_windows_qa_migrator"),Map.entry("server.port","443"),Map.entry("siger.windows.modo","COMPLETO"))){var p=base();p.put(entry.getKey(),entry.getValue());assertThrows(IllegalArgumentException.class,()->ArranqueWindows.configurar(p));}}
    @Test void rechazaPropiedadesQueActivenTransportesOCambienPerfiles(){for(String key:List.of("spring.profiles.active","server.address","institucional.formulario-completo.automatico","institucional.notificaciones.correo.modo","institucional.identidad.bootstrap.archivo")){var p=base();p.put(key,"no-admitido");assertThrows(IllegalArgumentException.class,()->ArranqueWindows.configurar(p));}}
    @Test void documentalExigeConfiguracionQAExplicitaYConservaTransportesCerrados(){var p=base();p.put("siger.windows.modo","DOCUMENTAL_QA_CALIFICADO");assertThrows(IllegalArgumentException.class,()->ArranqueWindows.configurar(p));p.put("institucional.documental.windows-configuracion","C:\\req\\testdata\\documental-win-0123456789abcdef0123456789abcdef\\windows.properties");var r=ArranqueWindows.configurar(p);assertEquals("true",r.get("institucional.documental.habilitada"));assertEquals("false",r.get("institucional.formulario-completo.automatico"));assertEquals("SIMULADO",r.get("institucional.notificaciones.correo.modo"));p.put("institucional.documental.windows-configuracion","C:\\agente\\config.properties");assertThrows(IllegalArgumentException.class,()->ArranqueWindows.configurar(p));}
    static Map<String,String> manual(){var p=base();p.put("siger.windows.modo","DOCUMENTAL_QA_CALIFICADO");p.put("institucional.documental.windows-configuracion","C:\\req\\testdata\\documental-win-0123456789abcdef0123456789abcdef\\windows.properties");p.put("siger.windows.formulario-manual","true");p.put("institucional.formulario-completo.origen-publico","https://formulario.defensorianinez.gob.cl");p.put("institucional.formulario-completo.token","t".repeat(64));p.put("operacion.token","o".repeat(64));p.put("institucional.configuracion-privada.directorio","C:\\req\\testdata\\runtime-qa-0123456789abcdef0123456789abcdef\\secrets");p.put("institucional.formulario-completo.ca-certificado",p.get("institucional.configuracion-privada.directorio")+"\\formulario-ca.pem");return p;}
    @Test void optInManualLocalNoHabilitaPlanificadorNiOtrosTransportes(){var r=ArranqueWindows.configurar(manual());assertEquals("true",r.get("institucional.formulario-completo.habilitado"));for(String key:List.of("institucional.formulario-completo.automatico","institucional.v2.habilitada","institucional.integracion.habilitada","institucional.notificaciones.correo.automatico","spring.flyway.enabled"))assertEquals("false",r.get(key));assertEquals("SIMULADO",r.get("institucional.notificaciones.correo.modo"));}
    @Test void optInAutomaticoQAExigeMismosControlesYActivaExclusion(){var p=manual();p.remove("siger.windows.formulario-manual");p.put("siger.windows.formulario-automatico","true");var r=ArranqueWindows.configurar(p);for(String key:List.of("institucional.formulario-completo.habilitado","institucional.formulario-completo.automatico","institucional.formulario-completo.exclusivo-qa"))assertEquals("true",r.get(key));for(String key:List.of("institucional.v2.habilitada","institucional.notificaciones.correo.automatico","spring.flyway.enabled"))assertEquals("false",r.get(key));p.put("siger.windows.formulario-manual","true");assertThrows(IllegalArgumentException.class,()->ArranqueWindows.configurar(p));}
    @Test void automaticoNoPermiteDestinosOAtributosInseguros(){for(var e:List.of(Map.entry("siger.windows.formulario-automatico","otro"),Map.entry("institucional.formulario-completo.origen-publico","https://example.invalid"),Map.entry("operacion.token","corto"),Map.entry("siger.windows.modo","PRELIMINAR_SIN_DOCUMENTAL"))){var p=manual();p.remove("siger.windows.formulario-manual");p.put("siger.windows.formulario-automatico","true");p.put(e.getKey(),e.getValue());assertThrows(IllegalArgumentException.class,()->ArranqueWindows.configurar(p));}}
    @Test void optInRequiereDocumentalTlsDestinoAprobadoCAPrivadaYAmbasCredenciales(){for(var entry:List.of(Map.entry("siger.windows.modo","PRELIMINAR_SIN_DOCUMENTAL"),Map.entry("institucional.formulario-completo.origen-publico","http://formulario.defensorianinez.gob.cl"),Map.entry("institucional.formulario-completo.origen-publico","https://example.invalid"),Map.entry("institucional.formulario-completo.ca-certificado","C:\\otra\\ca.pem"),Map.entry("institucional.formulario-completo.token","corta"),Map.entry("operacion.token","corta"),Map.entry("siger.windows.formulario-manual","false"))){var p=manual();p.put(entry.getKey(),entry.getValue());assertThrows(IllegalArgumentException.class,()->ArranqueWindows.configurar(p));}}
}
